import { useState, KeyboardEvent } from 'react';
import { JxInputField, JxChip, useControllableState } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (value: string[]) => void;
  label?: string;
  placeholder?: string;
}

export default function ArticleTagPicker({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagPickerProps) {
  const [tags, setTags] = useControllableState<string[]>(value, defaultValue, onChange);
  const [draft, setDraft] = useState('');

  const addTag = () => {
    const nextTag = draft.trim();
    if (!nextTag || tags.includes(nextTag)) {
      setDraft('');
      return;
    }
    setTags([...tags, nextTag]);
    setDraft('');
  };

  const removeTag = (tagToRemove: string) => {
    setTags(tags.filter((tag) => tag !== tagToRemove));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      setTags(tags.slice(0, -1));
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
      <JxInputField
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

